insert into events (slug, name, organiser, url, country, region, town_id, next_date, "window", km, vert, discipline, month, note, verified)
values
  ('lake-taupo-cycle-challenge', 'Lake Taupō Cycle Challenge', 'Lake Taupō Rotary Club (Rotary event operated by a Charitable Trust)', 'https://www.cyclechallenge.com', 'New Zealand', 'Waikato, North Island', null, '2026-11-28', 'Late November, annually', '{160}'::integer[], 1779, 'road', 'November', 'New Zealand''s biggest mass road ride, looping all the way around Great Lake Taupō on the headline Round the Lake course, with shorter road, gravel and mountain-bike options on the same weekend. Round the Lake riders must pass Tūrangi by 3:15pm and finish by 7pm or may be pulled from the course.', '2026-09-29'),
  ('whaka-100', 'Whaka 100', 'Nduro Events', 'https://www.whaka100.co.nz/', 'New Zealand', 'Rotorua, Bay of Plenty', null, '2026-10-23', 'Late October, annually', '{175,100,50,25,10}'::integer[], null, 'mtb', 'October', 'A marathon mountain-bike weekend built on the singletrack of Rotorua''s Whakarewarewa Forest, with distances from a short family loop up to the 175km Giant Miler. It draws thousands of riders and includes e-bike categories.', '2026-09-29'),
  ('le-race', 'Le Race', 'Le Race', 'https://lerace.co.nz/', 'New Zealand', 'Canterbury, South Island', null, '2027-03-20', 'March, annually', '{100}'::integer[], null, 'road', 'March', 'A point-to-point road ride from Christchurch over Banks Peninsula via Little River to the harbour village of Akaroa, with roots going back to 1935. Riders can enter solo, as a tandem, in relay pairs or in teams of four, and there is a king and queen of the mountain contest.', '2026-09-29'),
  ('motatapu-mtb', 'Motatapu Mountain Bike', 'Motatapu Events Ltd', 'https://motatapu.com/', 'New Zealand', 'Queenstown Lakes, Otago', null, '2027-03-06', 'Early March, annually', '{47}'::integer[], 1150, 'mtb', 'March', 'A one-way backcountry mountain-bike crossing through private high-country stations between Wanaka and Arrowtown, on land that is normally closed to the public. It runs alongside trail-running events and an e-bike ride on the same route.', '2026-09-29'),
  ('otway-odyssey', 'Otway Odyssey & Great Otway Gravel Grind', 'Rapid Ascent', 'https://otwayodyssey.rapidascent.com.au/', 'Australia', 'Forrest, Victoria', null, '2027-02-27', 'Late February, annually', '{100,50,30}'::integer[], null, 'mtb', 'February', 'A long-running marathon mountain-bike race on the singletrack and forest roads of the Otway Ranges, based in the small town of Forrest. A separate Great Otway Gravel Grind (106km and 50km) runs the same weekend, so it suits both MTB and gravel riders.', '2026-09-29'),
  ('transtasmania-mtb', 'TransTasmania MTB', 'TransTasmania MTB', 'https://transtasmaniamtb.com.au/', 'Australia', 'Tasmania', null, '2027-03-07', 'March, annually', '{}'::integer[], 4800, 'mtb', 'March', 'A fully supported, week-long enduro stage race moving across Tasmania from the Central Highlands to the West Coast and back via the East. Only the descents are timed, over 28 stages in six race days, and the trails are pitched at intermediate to advanced riders.', '2026-09-29'),
  ('devils-cardigan', 'The Devils Cardigan', 'The Devils Cardigan', 'https://www.devilscardigan.com.au/', 'Australia', 'North East Tasmania', 'derby', null, 'June, annually — 2027 date not yet published', '{106,54}'::integer[], 2300, 'gravel', 'June', 'A UCI Gravel World Series qualifier on forestry and back roads between Derby and Branxholm in north-east Tasmania, with the long course taking in the long climb to Ralph Falls. The short course has more bitumen and is open to e-bikes, singlespeeds and para riders.', '2026-09-29'),
  ('gravelista', 'Gravelista', 'Locale Events', 'https://www.gravelista.cc/', 'Australia', 'Seymour, Victoria', null, '2026-10-25', 'Late October, annually', '{135,95,50}'::integer[], null, 'gravel', 'October', 'A UCI Gravel World Series round, now based at Seymour Racecourse, with UCI age-group racing and recreational categories on the same courses. The top quarter of each UCI age category qualifies for the 2027 world championships, and e-bikes are allowed only in the recreational rides.', '2026-09-29'),
  ('great-victorian-bike-ride', 'TAC Great Victorian Bike Ride', 'Bicycle Network', 'https://bicyclenetwork.com.au/rides-and-events/great-victorian-bike-ride/', 'Australia', 'Goldfields, Victoria', null, '2026-11-23', 'Late November, annually', '{}'::integer[], null, 'road', 'November', 'A multi-day touring holiday rather than a race: riders camp together in a moving tent city with meals, luggage transfer and on-road support included. The 2026 route runs from Bendigo to Creswick over five days, and there is a one-day option from Castlemaine.', '2026-09-29'),
  ('tour-of-bright-fondo', 'Ride High Country Tour of Bright Fondo', 'Alpine Cycling Club', 'https://www.tourofbright.com.au/fondo.html', 'Australia', 'Alpine Valleys, Victoria', 'bright', '2026-12-05', 'Early December, alongside the Tour of Bright', '{84,33}'::integer[], null, 'road', 'December', 'A new non-competitive companion to the Tour of Bright stage race: two supported rides over consecutive days, up Tawonga Gap and then to The Horn on Mt Buffalo. Tawonga Gap is closed to traffic and the up lane on Mt Buffalo is closed; the last part to The Horn is gravel.', '2026-09-29'),
  ('bowral-classic', 'Bowral Classic', 'Cycling Classics (Bicycling Australia / Yaffa)', 'https://cyclingclassics.com.au/bowral/', 'Australia', 'Southern Highlands, New South Wales', null, '2026-10-18', 'October, annually', '{150,120,85}'::integer[], null, 'road', 'October', 'A road gran fondo on rolling Southern Highlands roads south-west of Sydney, run with road closures. It is ridden as a timed ride with three distances.', '2026-09-29'),
  ('mudgee-classic', 'Mudgee Classic', 'Cycling Classics (Bicycling Australia / Yaffa)', 'https://cyclingclassics.com.au/mudgee/', 'Australia', 'Mid-Western NSW', null, '2027-05-01', 'Early May, annually', '{170,120,90,65,55,35}'::integer[], null, 'mixed', 'May', 'A two-day wine-country festival: gravel rides on the Saturday and road rides on the Sunday, on the quiet farm roads around Mudgee. The shortest road option suits families and newer riders.', '2026-09-29'),
  ('thunderbolts-adventure', 'Thunderbolts Adventure', 'Graveleur', 'https://graveleur.cc/events/thunderbolts-adventure-10th-anniversary', 'Australia', 'Barrington Tops, New South Wales', null, null, 'Late April, annually — 2027 date not yet published', '{173,93,46}'::integer[], 3500, 'gravel', 'April', 'A gravel weekend based in Gloucester, heading up into the Barrington Tops, with the long Monument course being one of the country''s hardest one-day gravel routes. There is also a self-supported bikepacking option on set routes.', '2026-09-29'),
  ('gravel-n-granite', 'Gravel n Granite', 'The Saddlers MTB Club', 'https://thesaddlersmtbclub.com.au/gravel-n-granite-3', 'Australia', 'Tenterfield, New South Wales', null, null, 'Early March 2027 — organiser says final dates are still to be released', '{91,66,38,11}'::integer[], null, 'mixed', 'March', 'A weekend of gravel and mountain-bike riding through the granite country and national-park back roads around Tenterfield, near the Queensland border. It has an event village with local food and music, plus an adaptive-friendly course and a family ride.', '2026-09-29'),
  ('seven-gravel-race', 'SEVEN Gravel Race', 'Cycling Eventures Pty Ltd', 'https://sevengravelrace.com/', 'Australia', 'Blackwood Valley, Western Australia', null, null, 'May 2027 — date to be announced', '{125,90,49,25}'::integer[], 3200, 'gravel', 'May', 'A hilly one-day gravel race between Nannup and Balingup in WA''s South West, with route names that match the number of gravel sectors each one includes. It is a UCI Gravel World Series event, and the same region hosts the 2026 UCI Gravel World Championships.', '2026-09-29'),
  ('tour-de-brisbane', 'Tour de Brisbane', 'Ride Brisbane', 'https://tourdebrisbane.org/', 'Australia', 'Brisbane, Queensland', null, null, 'April, annually — 2027 date not yet published', '{110,80,50}'::integer[], null, 'road', 'April', 'A closed-road mass ride through inner Brisbane that finishes by crossing the traffic-free Story Bridge. It has been linked with the UCI Gran Fondo World Series, and there are three distances.', '2026-09-29'),
  ('dragon-ride', 'Dragon Ride', 'ASO UK', 'https://www.dragonride.co.uk/', 'United Kingdom', 'South Wales (Bannau Brycheiniog / Brecon Beacons)', null, '2027-06-13', null, '{222}'::integer[], 3500, 'road', 'June', 'Wales''s big sportive starts and finishes at Margam Park near Port Talbot and heads into the Brecon Beacons, with four routes from the short Cymru Classic up to the Dragon Devil. The Gran Fondo is the most popular choice and climbs Rhigos Mountain. The organiser says the 2027 routes are still to be confirmed.', '2026-09-29'),
  ('otztaler-radmarathon', 'Ötztaler Radmarathon', 'Ötztal Tourismus / Organising Committee of the Ötztaler Radmarathon', 'https://www.soelden.com/en/events-leisure-tips/events/oetztaler-cycle-marathon', 'Austria', 'Ötztal, Tyrol', null, '2027-08-29', null, '{227}'::integer[], 5500, 'road', 'August', 'A single, very long Alpine loop from Sölden crossing four Alpine passes, widely treated as one of the hardest one-day amateur rides in Europe. About 4,000 riders take part. There is one route only, so riders need to be ready for the full distance and climbing.', '2026-09-29'),
  ('vatternrundan', 'Vätternrundan', 'Motala AIF', 'https://www.vatternrundan.se/en/', 'Sweden', 'Motala, Östergötland', null, '2027-06-18', null, '{315,150,100}'::integer[], null, 'road', 'June', 'A lap of Lake Vättern from Motala that has run since 1966 and bills itself as the world''s largest recreational cycling event. The 315 km ride starts on a Friday evening and continues through the night into Saturday, with depots such as Jönköping and Hjo. Shorter options include Halvvättern (150 km, on 12 June 2027) and 100 km rides, plus separate gravel and MTB events.', '2026-09-29'),
  ('nove-colli', 'Gran Fondo Nove Colli', 'ASD G.C. Fausto Coppi', 'https://www.novecolli.it/', 'Italy', 'Cesenatico, Emilia-Romagna', null, '2027-05-23', null, '{200,137}'::integer[], 3814, 'road', 'May', 'A granfondo running since 1971 that starts on the Cesenatico seafront at sunrise and heads into the Romagna Apennines. The long route is 200 km and the medium 137 km, and a 107 km gravel option has been added. Entries for 2027 open on 5 December 2026.', '2026-09-29'),
  ('quebrantahuesos', 'Quebrantahuesos', 'Peña Ciclista Edelweiss (with S2 events)', 'https://www.quebrantahuesos.com/', 'Spain', 'Sabiñánigo, Aragon (Pyrenees)', null, null, 'Mid/late June, annually — 2027 date not yet published', '{200,85}'::integer[], null, 'road', 'June', 'Spain''s best-known Pyrenean marcha, based in Sabiñánigo, with the 200 km Quebrantahuesos and the 85 km Treparriscos. Places are limited and handed out by a draw that needs a small paid pre-registration. The 2026 edition had a 07:15 start and a 19:30 finish cutoff.', '2026-09-29'),
  ('paris-roubaix-challenge', 'Paris-Roubaix Challenge', 'A.S.O. (Amaury Sport Organisation)', 'https://www.timeto.com/en/event/paris-roubaix-challenge', 'France', 'Nord, Hauts-de-France', null, null, 'April 2027 (race weekend) — date to be announced', '{170,145,70}'::integer[], null, 'road', 'April', 'An amateur ride over the pro race''s cobbled sectors that finishes at the Roubaix velodrome. The 170 km Hell of the North route starts in Busigny and takes in 30 cobbled sections, while the 145 km and 70 km routes start in Roubaix. Pick a bike and tyres that can cope with long stretches of rough pavé.', '2026-09-29'),
  ('liege-bastogne-liege-challenge', 'Liège-Bastogne-Liège Challenge', 'A.S.O. (registration via Golazo)', 'https://lblchallenge.be/en/homepage/', 'Belgium', 'Ardennes, Wallonia', null, null, 'Late April, the day before the pro race — 2027 date not yet published', '{250,163,80}'::integer[], 4000, 'road', 'April', 'A Saturday ride over the climbs of ''La Doyenne'' in the Ardennes, starting from Banneux the day before the pro race. Climbs include La Redoute and the Roche-aux-Faucons, with the 250 km route taking in 12 climbs. Expect short, very steep ramps as well as the distance.', '2026-09-29'),
  ('amstel-gold-race-toerversie', 'Amstel Gold Race Toerversie', 'Stichting Amstel Gold Race', 'https://www.amstel.nl/amstelgoldrace/toerversie', 'Netherlands', 'Valkenburg, Limburg', null, '2027-04-17', null, '{240,200,150,125,100,65}'::integer[], null, 'road', 'April', 'The amateur version of the Amstel Gold Race rides the South Limburg hills the day before the pros race them, starting at the Shimano Experience Center in Valkenburg. Six distances make it one of the more accessible spring classic rides. Registration for 2027 opens on 1 October 2026 and stays open for one month.', '2026-09-29'),
  ('lardechoise', 'L''Ardéchoise', 'Association Ardéchoise', 'https://www.ardechoise.com/', 'France', 'Saint-Félicien, Ardèche', null, null, 'Mid-June, annually — 2027 date not yet published', '{285,241,230,186,167,134}'::integer[], null, 'road', 'June', 'A huge multi-day festival of mountain-road riding based in Saint-Félicien; the organisers counted 13,137 participants in 2026. The Saturday gives a choice of cyclosportive and cyclotourist routes, and there are 2–4 day formats as well as a separate gravel weekend in April. It suits groups whose riders want very different distances.', '2026-09-29'),
  ('la-stelvio-santini', 'La Stelvio Santini', 'La Stelvio Santini', 'https://www.lastelviosantini.com/?lang=en', 'Italy', 'Bormio, Lombardy', null, '2027-06-06', null, '{130,108,64}'::integer[], 4270, 'road', 'June', 'An untimed granfondo from Bormio built around the Passo dello Stelvio (2,758 m), with the Mortirolo also on the programme. All three road routes involve serious climbing even at the shortest distance. Gravel routes of 44 km and 70 km are being added for 2027.', '2026-09-29'),
  ('dreilandergiro', 'Dreiländergiro', 'BikeClub Nauders', 'https://www.dreilaendergiro.at/en/', 'Austria', 'Nauders, Tyrol', null, '2027-06-27', null, '{168,120}'::integer[], 3600, 'road', 'June', 'A cycling marathon from Nauders that crosses Austria, Italy and Switzerland in a single day, with the Stelvio Pass as the high point on both routes. The Vinschgau route is 120 km and the Engadin route is 168 km. Each includes more than 3,000 m of climbing.', '2026-09-29'),
  ('styrkeproven', 'Styrkeprøven', 'Styrkeprøven AS', 'https://styrkeproven.no/?lang=en', 'Norway', 'Trondheim to Oslo', null, '2027-06-18', null, '{515,176}'::integer[], 4220, 'road', 'June', 'A point-to-point ride from Trondheim to Oslo that has run since 1967, with starts from Munkegata square in the early morning and a finish in Groruddalen, Oslo. Shorter options start in Lillehammer (176 km) and Eidsvoll. Plan the logistics carefully, because the start and finish are in different cities.', '2026-09-29'),
  ('mondsee-5-seen-radmarathon', 'Mondsee 5 Seen Radmarathon', 'CFX Events GmbH', 'https://www.mondsee-radmarathon.com/', 'Austria', 'Mondsee, Salzkammergut', null, '2027-06-20', null, '{200,140,75}'::integer[], 2600, 'road', 'June', 'A lake-country marathon in the Salzkammergut that links five lakes around Mondsee. About 2,500 riders take part, and it is gentler than the Alpine events: the 75 km route has only 400 m of climbing. There is also a handbike category.', '2026-09-29'),
  ('arlberg-giro', 'Arlberg Giro', 'Tourism Association St. Anton am Arlberg', 'https://arlberg-giro.com/en/home', 'Austria', 'St. Anton am Arlberg, Tyrol', null, '2027-08-01', null, '{150}'::integer[], 2500, 'road', 'August', 'A loop that starts and finishes in St. Anton, going over the Arlberg Pass, down the Klostertal and Montafon valleys, and over the Silvretta High Alpine Road. It covers Tyrol and Vorarlberg on a single route. Riders come from more than 30 nations.', '2026-09-29'),
  ('alpenbrevet', 'Swiss Cycling Alpenbrevet', 'Swiss Cycling Alpenbrevet', 'https://alpenbrevet.ch/en/', 'Switzerland', 'Andermatt, Uri', null, '2027-09-04', null, '{}'::integer[], null, 'road', 'September', 'A non-competitive ride over the high Swiss passes from Andermatt, with four tiers from Bronze (two passes) to Platinum (five passes). The focus is on finishing, not racing. Registration for 2027 opens in autumn 2026.', '2026-09-29'),
  ('cyclotour-du-leman', 'Cyclotour du Léman', 'Cyclotour du Léman', 'https://cyclotour.ch/', 'Switzerland', 'Lausanne, Vaud', null, '2026-10-18', null, '{176,112,64}'::integer[], 890, 'road', 'October', 'A lap of Lake Geneva from Lausanne that passes through Switzerland and France, with shorter one-way options between Évian and Lausanne. It is mostly flat lakeside riding past vineyards, with only 890 m of climbing on the full lap. The organisers present it as a pace ride rather than a race.', '2026-09-29'),
  ('gran-fondo-il-lombardia', 'Gran Fondo Il Lombardia Felice Gimondi', 'RCS Sports & Events', 'https://gfilombardia.it/en/', 'Italy', 'Bergamo, Lombardy', null, '2026-10-11', null, '{108}'::integer[], 2400, 'road', 'October', 'The amateur ride linked to the autumn Monument is now based in Bergamo and named after Felice Gimondi. It takes in the Valico di Valcava and Selvino climbs, with gradients up to 17%. It runs the day after the pro race, and the field is about 2,000 riders.', '2026-09-29'),
  ('milano-sanremo-amatori', 'Milano–Sanremo Amatori', 'Unione Cicloturistica Sanremo', 'https://milano-sanremo.org/en/', 'Italy', 'Milan to Sanremo (Lombardy / Liguria)', null, '2027-06-06', null, '{296}'::integer[], null, 'road', 'June', 'An untimed ride over the full classic route from the outskirts of Milan to San Remo, crossing the Turchino before the coastal Capi, the Cipressa and the Poggio. At about 296 km, it is one of the longest one-day amateur rides anywhere. Riders need a valid sports licence or a day licence, which requires a medical certificate.', '2026-09-29'),
  ('tour-transalp', 'TOUR Transalp', 'Delius Klasing', 'https://event.delius-klasing.de/en/tour-transalp/', 'Austria', 'Lienz (Austria) to Riva del Garda (Italy)', null, '2027-06-20', null, '{750}'::integer[], 17000, 'road', 'June', 'A seven-stage road race across the Alps from Lienz to Riva del Garda, ridden in teams of two. The organiser puts the total at around 750 km and 17,000 m of climbing. Riders need a partner and the ability to cope with back-to-back mountain days.', '2026-09-29'),
  ('leroica', 'L''Eroica', 'Eroica Italia SSD', 'https://www.eroica.cc/en/events/leroica/', 'Italy', 'Gaiole in Chianti, Tuscany', null, '2026-10-03', null, '{211,133,106,81,45}'::integer[], 3700, 'mixed', 'October', 'The original vintage-bike ride, held in Gaiole in Chianti since 1997, on a mix of Tuscan tarmac and white gravel strade bianche. Bikes must be built in or before 1987, with down-tube shifters and toe clips or period pedals rather than clipless ones. The long route is 211 km with over 3,700 m of climbing.', '2026-09-29'),
  ('the-traka', 'The Traka', 'Klassmark', 'https://www.thetraka.com/', 'Spain', 'Catalonia', 'girona', '2027-04-30', null, '{202,100}'::integer[], null, 'gravel', 'April', 'Europe''s best-known gravel race, run over a long weekend out of Girona with several distance options. The 100 km route is roughly four-fifths unpaved, and the longer routes are much bigger days. Riders from the Santa Vall satellite event get priority entry.', '2026-09-29'),
  ('santa-vall', 'Santa Vall by The Traka', 'By the Traka / Klassmark', 'https://www.santavall.com/', 'Spain', 'Catalonia', 'girona', '2027-02-05', null, '{139,83}'::integer[], null, 'gravel', 'February', 'A two-stage winter gravel event in the Vall de Llémena, north-west of Girona. Stage 1 runs 139 km from Sant Gregori to Girona and stage 2 is an 83 km loop from Sant Gregori, on forest tracks, trails and some tarmac. It sits in the Gravel Earth Series and is a common season opener.', '2026-09-29'),
  ('dirty-reiver', 'Dirty Reiver', 'Focal Events', 'https://dirtyreiver.co.uk/', 'United Kingdom', 'Northumberland (Kielder Forest)', null, '2027-04-23', null, '{280,200,130,65}'::integer[], null, 'gravel', 'April', 'The UK''s classic long-distance gravel ride, on forest roads through Kielder Forest on the English–Scottish border. Four distances are offered, and the new 280 km Epic is ridden in pairs. The routes have between one and four feed stations.', '2026-09-29'),
  ('the-gralloch', 'The Gralloch', 'Red On Group Limited', 'https://www.grallochgravel.com/', 'United Kingdom', 'Dumfries and Galloway, Scotland', null, '2027-05-14', null, '{323,111,53}'::integer[], 1761, 'gravel', 'May', 'A gravel festival in Galloway Forest Park, based at Gatehouse of Fleet. It has a UCI Gravel World Series race over 111 km, open to amateurs in age-group categories, plus a 323 km ultra and two non-competitive sportive routes. The race route is more than 80% gravel.', '2026-09-29'),
  ('grinduro-scotland', 'Grinduro Scotland', 'Grinduro', 'https://grinduro.com/scotland/', 'United Kingdom', 'Dumfries and Galloway, Scotland', null, null, 'Late June, annually — 2027 date not yet published', '{100}'::integer[], null, 'gravel', 'June', 'A mixed-terrain gravel and MTB weekend at the Drumlanrig Castle estate. Everyone starts together for a loop of about 100 km, but only four short timed segments count towards the result. Camping, music and food are part of the weekend.', '2026-09-29'),
  ('nova-eroica-buonconvento', 'Nova Eroica Buonconvento', 'L''Eroica srl', 'https://www.eroica.cc/en/events/nova-eroica-buonconvento/', 'Italy', 'Tuscany', null, '2027-04-11', null, '{290,131,96,67,43}'::integer[], null, 'gravel', 'April', 'A gravel fondo on the white roads of the Crete Senesi, south of Siena, for gravel, cyclocross or modern road bikes. On the medium and long routes, timed sections alternate with untimed stretches. There is also a 290 km Epic Route that starts at 4 am.', '2026-09-29'),
  ('nova-eroica-prosecco-hills', 'Nova Eroica Prosecco Hills', 'L''Eroica srl', 'https://www.eroica.cc/en/events/nova-eroica-prosecco-hills/', 'Italy', 'Veneto', null, '2027-05-02', null, '{119,94,55}'::integer[], 2140, 'gravel', 'May', 'A gravel fondo through the vineyard hills of Conegliano–Valdobbiadene, which are UNESCO-listed. All three routes combine timed sections with untimed riding. Gravel, cyclocross and modern road bikes are allowed.', '2026-09-29'),
  ('titan-desert-morocco', 'Škoda Titan Desert Morocco', 'RPM Racing S.L.', 'https://titanworldseries.com/en/', 'Morocco', 'Sahara', null, '2027-04-25', null, '{340}'::integer[], 6000, 'mixed', 'April', 'A six-day desert stage race run by a Barcelona-based organiser, with riders living in a shared bivouac camp. For the first time, the 2027 edition has separate gravel and MTB routes. Expect long days on sand and rough tracks.', '2026-09-29'),
  ('titan-desert-almeria', 'Škoda Titan Desert Almería', 'RPM Racing S.L.', 'https://skodatitandesertalmeria.titanworldseries.com/en/', 'Spain', 'Andalusia (Almería)', null, '2026-10-01', null, '{300}'::integer[], 5000, 'mtb', 'October', 'A four-stage MTB race, open to the public, through the dry, varied landscapes of Almería. The entry fee covers lodging, meals and safety equipment. It is the European, shorter sister event of the Morocco race.', '2026-09-29'),
  ('grand-raid-bcvs', 'Grand Raid BCVS', 'Grand-Raid BCVS', 'https://grand-raid-bcvs.ch/en/', 'Switzerland', 'Valais', null, '2027-08-21', null, '{125,93,68,54,37}'::integer[], 5025, 'mtb', 'August', 'A point-to-point Alpine MTB marathon that finishes in Grimentz, with shorter versions starting in villages along the way. The full route from Verbier goes over the Pas de Lona at more than 2,700 m. There are strict intermediate cutoffs, and riders who miss one are taken out of the race.', '2026-09-29'),
  ('salzkammergut-trophy', 'Salzkammergut Trophy', 'Salzkammergut Trophy', 'https://www.salzkammergut-trophy.at/', 'Austria', 'Upper Austria (Salzkammergut)', null, null, 'Mid-July, annually — 2027 date not yet published', '{202,120,75,58,55,22}'::integer[], null, 'mtb', 'July', 'Austria''s biggest MTB marathon, based in Bad Goisern and passing through the lake country around Hallstatt. Its 202 km extreme route is one of the longest one-day MTB marathons in Europe, and there are many shorter options. Registration for 2027 is open, but the date is not yet published.', '2026-09-29'),
  ('megavalanche-alpe-dhuez', 'Megavalanche Alpe d''Huez', 'UCC Sport Event', 'https://www.ucc-sportevent.com/en/megavalanche-alpe-dhuez-en/', 'France', 'Isère (Oisans)', null, '2027-07-09', null, '{21}'::integer[], null, 'mtb', 'July', 'The original mass-start downhill marathon, starting on the glacier at Pic Blanc (3,330 m) and dropping 2,600 m to Allemond. Qualifying runs early in the weekend decide who starts in the main Sunday race, and there are separate amateur, women''s and e-bike races.', '2026-09-29'),
  ('roc-dazur', 'Roc d''Azur', 'ASO (Amaury Sport Organisation)', 'https://www.rocazur.com/', 'France', 'Var (Fréjus)', null, '2026-10-07', null, '{101,55,41,32,29}'::integer[], 2485, 'mtb', 'October', 'A five-day MTB festival held at Fréjus on the Mediterranean coast, with races, recreational rides, gravel and e-bike events. The Sunday highlights are the 100.6 km Roc Marathon and the 55 km Roc d''Azur race. It is one of the largest mountain bike gatherings in Europe.', '2026-09-29'),
  ('hero-dolomites', 'HERO Südtirol Dolomites', 'HERO (amateur sports company)', 'https://www.herodolomites.com/en', 'Italy', 'South Tyrol (Val Gardena)', null, '2027-06-12', null, '{86,71,60}'::integer[], null, 'mtb', 'June', 'A high-mountain MTB marathon around the Sella massif, starting and finishing in Selva Val Gardena. It has three distances, the longest being 86 km, and a team category has been added. Entry is through the Datasport portal.', '2026-09-29'),
  ('swiss-epic', 'Swiss Epic', 'Epic Series', 'https://www.epic-series.com/races/swissepic', 'Switzerland', 'Graubünden', null, '2027-08-17', null, '{300}'::integer[], 10000, 'mtb', 'August', 'A five-day MTB stage race for two-rider teams, based in Davos for 2027, with a new route each year. Amateurs race alongside professionals over mountain passes, flow trails and bike parks. Past riders got early registration before general entry opened.', '2026-09-29'),
  ('riva-bike-marathon', 'Bike Marathon — BIKE Festival Riva del Garda', 'Garda Dolomiti – Azienda per il Turismo S.p.A.', 'https://www.bikefestivalriva.com/en/competitions/bike-marathon', 'Italy', 'Trentino (Lake Garda)', null, '2027-05-02', null, '{84,59,31}'::integer[], 3434, 'mtb', 'May', 'The marathon on the final day of the Riva del Garda bike festival, starting from the town centre on the north shore of Lake Garda. Riders choose from three loops, from a beginner-friendly option to the steep 84 km Ronda Extrema. The festival itself runs for three days.', '2026-09-29'),
  ('the-mid-south', 'The Mid South', 'The Mid South', 'https://www.midsouthgravel.com/', 'USA', 'Oklahoma', null, null, 'March 2027 — exact date not shown on official site', '{161,80,19}'::integer[], null, 'gravel', 'March', 'Early-season gravel weekend on the dirt roads around Stillwater, with 12, 50 and 100-mile rides plus a half marathon and 50K run. Weather in March can change conditions a lot from year to year. Entry is by ticket; transfers close on 1 March 2027.', '2026-09-29'),
  ('the-big-lost-rebeccas-private-idaho', 'The Big Lost (Rebecca''s Private Idaho)', 'Bike Monkey', 'https://biglostidaho.com/', 'USA', 'Idaho', null, '2027-09-08', null, '{190,167,92,80,56,31}'::integer[], 2158, 'gravel', 'September', 'Rebecca''s Private Idaho now sits inside a multi-day gravel festival based in Sun Valley and Ketchum. Two shorter stages lead into the Saturday main event, where riders choose from four distances up to 118 miles on high-desert backcountry roads.', '2026-09-29'),
  ('barry-roubaix', 'Barry-Roubaix', 'Pavement Ends Inc.', 'https://www.barry-roubaix.com/', 'USA', 'Michigan', null, '2027-04-17', null, '{161,100,58,29}'::integer[], 2134, 'gravel', 'April', 'One of the largest gravel races in the US, run on rolling dirt roads out of Hastings in rural Michigan. Four distances from 18 to 100 miles; the 100-mile Psycho Killer is capped at 400 riders. Registration opens 14 November on BikeReg.', '2026-09-29'),
  ('bwr-arizona', 'Belgian Waffle Ride Arizona', 'Belgian Waffle Ride (Monuments of Cycling)', 'https://www.belgianwaffleride.bike/pages/belgian-waffle-ride-az', 'USA', 'Arizona', null, '2027-03-07', null, '{196,110,54}'::integer[], 2286, 'gravel', 'March', 'The desert edition of the BWR series, starting from McDowell Mountain Park near Scottsdale. The 122-mile Waffle is 58% unpaved, mixing rough dirt roads and washes in the Tonto forest with singletrack and some steep paved climbs. Shorter Wafer and Wanna routes are offered.', '2026-09-29'),
  ('bwr-mexico', 'Belgian Waffle Ride México', 'Belgian Waffle Ride México', 'https://www.bwrmexico.com/en', 'Mexico', 'Querétaro', null, '2026-11-21', null, '{}'::integer[], null, 'gravel', 'November', 'Mexican edition of the Belgian Waffle Ride series, held around Tequisquiapan in Querétaro state. Routes suit gravel or mountain bikes and follow the BWR Waffle/Wafer/Wanna distance format; check the event site for this year''s course lengths.', '2026-09-29'),
  ('chequamegon-mtb-festival', 'Chequamegon MTB Festival', 'Life Time', 'https://www.cheqmtb.com/', 'USA', 'Wisconsin', null, '2027-09-18', null, '{64,26}'::integer[], null, 'mtb', 'September', 'Long-running mass-start mountain bike race in the northern Wisconsin woods between Hayward and Cable. The Chequamegon 40 uses the Birkie ski trail, forest roads and snowmobile routes; the Short & Fat covers 16 miles. Entry opens via registration or lottery, with early access for Life Time members.', '2026-09-29'),
  ('bc-bike-race', 'BC Bike Race', 'BC Bike Race', 'https://www.bcbikerace.com/', 'Canada', 'British Columbia', null, '2027-05-24', null, '{}'::integer[], null, 'mtb', 'May', 'Five-day all-inclusive mountain bike stage race moving between Whistler, Squamish, Cumberland, Parksville and North Cowichan, using BC Ferries between venues. Riders choose a classic XC or an enduro format. For 2027 the race moves to late May from its usual July slot.', '2026-09-29'),
  ('breck-epic', 'Breck Epic', 'Breck Epic', 'https://www.breckepic.com/', 'USA', 'Colorado', null, '2027-08-15', null, '{}'::integer[], null, 'mtb', 'August', 'Six-day mountain bike stage race at high altitude, with each backcountry loop starting and finishing near downtown Breckenridge. Loops run between 35 and 50 miles on trails across Summit and Park counties; a three-day version is also offered.', '2026-09-29'),
  ('whiskey-off-road', 'Whiskey Off-Road', 'Epic Rides', 'https://www.epicrides.com/events/whiskey-off-road', 'USA', 'Arizona', null, '2027-04-30', null, '{80,40,30}'::integer[], null, 'mtb', 'April', 'Three-day mountain bike festival in downtown Prescott with amateur backcountry routes of about 15, 25 and 50 miles through Prescott National Forest singletrack, doubletrack and gravel. A pro race, expo and street party run alongside. Registration opens on Black Friday.', '2026-09-29'),
  ('pisgah-111', 'Pisgah 111', 'Pisgah Productions', 'https://www.pisgahproductions.com/events/pisgah-111k-mtb-race/', 'USA', 'North Carolina', null, '2026-10-03', null, '{105}'::integer[], 3109, 'mtb', 'October', 'Tough backcountry endurance mountain bike race in Pisgah National Forest near Brevard, based around Davidson River Campground. The 65.1-mile course packs in 10,200 feet of climbing on rocky, rooty trails and forest roads, with four rest areas.', '2026-09-29'),
  ('iceman-cometh-challenge', 'Iceman Cometh Challenge', 'The Festival Foundation', 'https://www.iceman.com/', 'USA', 'Michigan', null, '2026-11-07', null, '{48}'::integer[], null, 'mtb', 'November', 'Point-to-point 30-mile mountain bike race from Kalkaska to Timber Ridge Resort in Traverse City, held in early November when snow or cold is common. Amateurs start in waves in the morning, with the pro race later in the day; a shorter Slush Cup is also offered.', '2026-09-29'),
  ('el-tour-de-tucson', 'El Tour de Tucson', 'Perimeter Bicycling', 'https://eltourdetucson.org/el-tour-de-tucson/', 'USA', 'Arizona', null, '2026-11-21', null, '{164,100,51}'::integer[], null, 'road', 'November', 'Large charity road ride that has run since 1983, starting and finishing at the Tucson Convention Center. The longer routes loop through Sonoran Desert country past Colossal Cave and Old Spanish Trail, with aid stations roughly every 12 miles.', '2026-09-29'),
  ('rbc-granfondo-whistler', 'RBC GranFondo Whistler', 'RBC GranFondo', 'https://www.rbcgranfondo.com/event/whistler', 'Canada', 'British Columbia', null, '2027-09-11', null, '{146,122,55}'::integer[], 2300, 'road', 'September', 'Traffic-free ride from Stanley Park in Vancouver up the Sea to Sky Highway to Whistler. The 122 km Gran Fondo climbs 2,300 m; the 146 km Forte is capped at 600 riders, and a 55 km Medio starts in Whistler. The 2026 edition sold out.', '2026-09-29'),
  ('triple-bypass', 'Triple Bypass', 'Shift Events', 'https://www.triplebypass.org/', 'USA', 'Colorado', null, '2027-07-10', null, '{177}'::integer[], 3048, 'road', 'July', 'One-day supported road ride from Evergreen to Avon over Juniper, Loveland and Vail passes: 110 miles with more than 10,000 feet of climbing at high altitude. A Double Bypass from Empire covers Loveland and Vail only.', '2026-09-29'),
  ('ragbrai', 'RAGBRAI', 'RAGBRAI (Register''s Annual Great Bicycle Ride Across Iowa)', 'https://ragbrai.com/', 'USA', 'Iowa', null, '2027-07-24', null, '{}'::integer[], null, 'road', 'July', 'Week-long ride across Iowa held every year since 1973 in the last full week of July, with overnight stops in host towns and a new route each year. Daily stages range from 35 to 85 miles. Entry is first-come, first-served from 15 November, with weeklong and day-rider options.', '2026-09-29'),
  ('hotter-n-hell-hundred', 'Hotter''N Hell Hundred', 'Wichita Falls Bicycling Club, Inc', 'https://www.hh100.org/', 'USA', 'Texas', null, null, 'Late August, annually; 2027 date not yet published', '{}'::integer[], null, 'road', 'August', 'Long-running late-summer century in Wichita Falls, held since 1982, known for the North Texas heat. Road distances run from 10 miles up to 100, and the weekend also includes gravel and mountain bike routes plus a trail run.', '2026-09-29'),
  ('blue-sky-hill-climb', 'Bob Cook Memorial Blue Sky Hill Climb', 'Shift Events', 'https://www.bicyclerace.com/hill-climb-information-2026', 'USA', 'Colorado', null, null, 'Late July, annually; 2027 date not yet published', '{44}'::integer[], 2046, 'road', 'July', 'Timed road climb from Idaho Springs to the 14,130-foot summit of Mt. Blue Sky (formerly Mount Evans), on the highest paved road in North America. The 27.4-mile course gains 6,714 feet. Open to amateurs in age-group categories from 15 up; no USA Cycling licence needed.', '2026-09-29'),
  ('grinduro-california', 'Grinduro California', 'Sierra Buttes Trail Stewardship', 'https://grinduro.com/california/', 'USA', 'California', null, null, 'Mid-September, annually; 2027 date not yet published', '{82,37}'::integer[], 2195, 'gravel', 'September', 'Gravel-and-dirt event based at the fairgrounds in Quincy in the northern Sierra. Only four short timed segments count toward results, so most of the 51-mile loop is ridden at your own pace. The shorter Grindurito has two segments.', '2026-09-29'),
  ('lost-and-found-gravel', 'Lost and Found Gravel', 'Sierra Buttes Trail Stewardship', 'https://lostandfoundbikeride.com/', 'USA', 'California', null, '2027-06-19', null, '{159,93,64}'::integer[], null, 'gravel', 'June', 'Gravel race and ride from Portola in the northeastern Sierra, with 99, 58 and 40-mile routes on forest roads. It is run by the same trail group that organises Grinduro California, so the two events share organiser and region.', '2026-09-29'),
  ('letape-ciudad-de-mexico', 'L''Étape Ciudad de México by Tour de France', 'L''Étape by Tour de France', 'https://ciudaddemexico.letapeseries.com/', 'Mexico', 'Mexico City', null, '2026-11-15', null, '{110,60,40}'::integer[], 936, 'road', 'November', 'Mexico City edition of the Tour de France-licensed L''Étape amateur series. The 110 km long route climbs 936 m, with 60 km and 40 km options. Visitors should allow for Mexico City''s high altitude.', '2026-09-29'),
  ('masters-tour-of-chiang-mai', 'Masters Tour of Chiang Mai', 'Creative Minds Asia Limited Partnership', 'https://masterstourofchiangmai.com/', 'Thailand', 'Chiang Mai', 'chiangmai', '2026-10-16', '16–19 October 2026', '{}'::integer[], null, 'road', 'October', 'A four-day stage race for masters-age riders, run in age categories on the roads around Chiang Mai; no UCI licence is needed, though it is sanctioned by the Thai Cycling Federation. The 2025 edition combined road stages, a circuit race and a closing individual time trial up Doi Suthep. Categories are competitive, so this suits riders who want to race rather than tour.', '2026-09-29'),
  ('tour-de-okinawa-citizen-race', 'Tour de Okinawa Citizen Road Race', 'Tour de Okinawa', 'https://www.tour-de-okinawa.jp/citizen-road-race.html', 'Japan', 'Okinawa', null, '2026-11-08', 'Early-to-mid November, annually', '{200,140,100,50}'::integer[], null, 'road', 'November', 'Amateur races held alongside the Tour de Okinawa, with the longest citizen category covering 200 km through the forested Yanbaru region of northern Okinawa. Categories are split by age and gender; most long-distance classes are listed for men only, while women race a 50 km category. Entries are capped per class and the 2026 entry window closed on 19 September.', '2026-09-29'),
  ('mt-fuji-hill-climb', 'Mt. Fuji Hill Climb', 'Mt. Fuji Hill Climb Executive Committee (Mt.富士ヒルクライム大会実行委員会)', 'https://www.fujihc.jp/', 'Japan', 'Yamanashi', null, null, 'Early June, annually — 2027 date not yet published', '{25}'::integer[], 1270, 'road', 'June', 'A timed mass-participation climb up the Fuji Subaru Line from Fuji Kitaroku Park to Mt Fuji''s fifth station, with the road closed to traffic on race day. The gradient is steady rather than steep, so it attracts first-timers as well as fast climbers. Entry is online through RUNNET, with the 2026 window running February to March.', '2026-09-29'),
  ('yak-attack', 'Yak Attack', 'Multi Terrain Biking (Mountain Biking Worldwide)', 'https://www.mtb-worldwide.com/the-yak-attack/', 'Nepal', 'Annapurna / Gandaki', null, null, '2026 edition held 22 May–1 June; 2027 dates not yet published', '{}'::integer[], null, 'mtb', 'May', 'A multi-day mountain bike stage race in the Nepal Himalaya, billed as the highest MTB race on earth, with the route crossing the Thorong La pass at 5,416 m in past editions. Expect rough trails, suspension bridges, possible snow and big temperature swings. The organiser only accepts riders with solid mountain bike experience.', '2026-09-29'),
  ('spinneys-dubai-92-cycle-challenge', 'Spinneys Dubai 92 Cycle Challenge', 'Spinneys, with Dubai Sports Council', 'https://cyclechallenge.ae/', 'United Arab Emirates', 'Dubai', null, '2027-02-07', 'February, annually', '{92}'::integer[], null, 'road', 'February', 'A 92 km closed-road ride starting and finishing at Expo City Dubai, now in its 17th edition. It counts as a qualifier for the UCI Gran Fondo World Championships, so the front of the field races hard while most riders ride it as a sportive. Family and junior rides run on the day before.', '2026-09-29'),
  ('uci-gran-fondo-colombia-medellin', 'UCI Gran Fondo Colombia', 'Riders Sports', 'https://ucigranfondocolombia.com/', 'Colombia', 'Antioquia', 'medellin', '2026-11-29', '29 November 2026', '{138,91}'::integer[], null, 'road', 'November', 'A UCI Gran Fondo World Series round based in Medellín that doubles as a qualifier for the amateur world championships. Riders choose between a gran fondo and a shorter medio fondo, both starting in the city. This is the event''s second edition; it moved to Medellín after a first running in Bogotá.', '2026-09-29'),
  ('gran-fondo-nairo-quintana', 'Gran Fondo Nairo Quintana', 'Gran Fondo Nairo Quintana', 'https://granfondonairoquintana.com/', 'Colombia', 'Bolívar', null, '2026-10-11', 'Festival 9–11 October 2026; main road ride Sunday 11 October', '{186,106,50}'::integer[], 970, 'road', 'October', 'The eighth edition of Nairo Quintana''s festival ride, based in Cartagena this year, with point-to-point routes linking the city to towns across Bolívar department. The climbing is modest for the distance, so heat and humidity are likely to be the bigger test. The festival weekend also has running races and an XCO mountain bike race.', '2026-09-29'),
  ('letape-cunha', 'L''Étape Cunha by Tour de France', 'L''Étape Brasil by Tour de France (presented by Nubank)', 'https://cunha.letapeseries.com/', 'Brazil', 'São Paulo', null, '2027-04-02', 'Event weekend 2–4 April 2027', '{111,53}'::integer[], 2400, 'road', 'April', 'A Tour de France–branded sportive in the hill town of Cunha, where L''Étape Brasil held its first three editions. The long route has a lot of climbing for its distance, and a much gentler short route is also offered. The event runs across a weekend.', '2026-09-29'),
  ('letape-campos-do-jordao', 'L''Étape Campos do Jordão by Tour de France', 'L''Étape Brasil by Tour de France (presented by Nubank)', 'https://camposdojordao.letapeseries.com/', 'Brazil', 'São Paulo', null, '2027-09-26', 'Event weekend from 26 September 2027', '{107,66}'::integer[], 2300, 'road', 'September', 'The season-closing L''Étape Brasil event, held in the mountain resort town of Campos do Jordão. Both routes are hilly, and the long course has a lot of climbing for its distance. Registration for 2027 is listed as opening soon.', '2026-09-29'),
  ('la-ruta-de-los-conquistadores', 'La Ruta de los Conquistadores', 'Spartan', 'https://racelaruta.com/en/events/la-ruta-en/', 'Costa Rica', 'Puntarenas to Limón', null, '2026-10-29', '29–31 October 2026', '{}'::integer[], null, 'mtb', 'October', 'A three-day mountain bike crossing of Costa Rica from the Pacific to the Caribbean, first run in 1993. Stages run Jacó to San José, San José to Turrialba, then a loop from Turrialba down towards Limón, climbing from sea level to above 3,000 m past volcanic terrain, jungle and river crossings. Full stage distances had not been published at the time of checking.', '2026-09-29'),
  ('transandes-challenge-patagonia', 'Transandes Challenge', 'Transandes Challenge', 'https://www.transandeschallengepatagonia.com/', 'Chile', 'Araucanía', null, '2027-03-03', '3–7 March 2027', '{340}'::integer[], 8000, 'mtb', 'March', 'A five-stage mountain bike race based around Lonquimay and the Corralco ski resort in Chilean Patagonia, now in its 18th year. Riders cover native araucaria forest, volcanic sand and technical singletrack beneath the Lonquimay and Sierra Nevada volcanoes, with one stage including a time trial. Most entry packages include accommodation at Hotel Corralco.', '2026-09-29'),
  ('947-ride-joburg', '947 Ride Joburg', 'City of Johannesburg', 'https://ridejoburg.co.za/road.html', 'South Africa', 'Gauteng', null, '2026-11-22', 'Late November, annually', '{97}'::integer[], 1398, 'road', 'November', 'A large closed-road ride through Johannesburg that starts on the M1 highway and finishes at the Kyalami Grand Prix circuit. Start groups are seeded on recent race results, and seeded entries close earlier than unseeded ones.', '2026-09-29'),
  ('wines2whales', 'FNB Wines2Whales', 'Epic Series (IRONMAN Group)', 'https://www.epic-series.com/races/wines2whales', 'South Africa', 'Western Cape', null, '2026-11-06', 'Three back-to-back editions, 6–15 November 2026', '{187}'::integer[], 3750, 'mtb', 'November', 'A three-day mountain bike stage race for teams of two, linking the Lourensford and Oak Valley wine estates with Benguela Cove on the coast. It runs as three separate editions (Chardonnay, Pinotage and Shiraz) on the same route over roughly ten days, mixing gravel roads with flowing singletrack.', '2026-09-29'),
  ('sani2c', 'KAP sani2c', 'sani2c', 'https://sani2c.co.za/', 'South Africa', 'KwaZulu-Natal', null, '2027-05-05', 'Adventure 5–7 May 2027; OG 6–8 May 2027', '{270}'::integer[], null, 'mtb', 'May', 'A three-stage mountain bike race from a farm near the Sani Pass in the southern Drakensberg down to Scottburgh on the Indian Ocean. It runs as two staggered editions: the OG, which includes the UCI race and allows e-bikes, and the Adventure. The event is closely tied to community development projects along the route.', '2026-09-29'),
  ('cape-pioneer-trek', 'Cape Pioneer Trek', 'Dryland Events', 'https://capepioneer.co.za/', 'South Africa', 'Western Cape', null, null, 'Late September — 2026 edition held 22–26 September; 2027 dates not announced', '{}'::integer[], null, 'mtb', 'September', 'A mountain bike stage race around Oudtshoorn, taking in the Karoo desert landscape, the Klein Karoo mountains and Garden Route forest. The relaunched event now runs on a shorter route than the original Cape Pioneer. Stage details for future editions had not been published at the time of checking.', '2026-09-29')
